    refresh_token: t.refresh_token,
    access_token: t.access_token,
    // gợi ý thêm để lưu log:
    expires_in: t.expires_in,                  // giây
    fetched_at: new Date().toISOString(),      // dấu thời gian ghi
  }
}];

